create table public.payments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),student_bill_id uuid not null references public.student_bills(id),account_id uuid not null references public.finance_accounts(id),receipt_number text not null,amount numeric(14,2) not null check(amount>0),paid_at timestamptz not null default timezone('utc',now()),status text not null default 'CONFIRMED' check(status in('PENDING','CONFIRMED','VOID','REFUNDED')),reference text,created_at timestamptz not null default timezone('utc',now()),unique(tenant_id,receipt_number));create index payments_tenant_paid_idx on public.payments(tenant_id,paid_at);alter table public.payments enable row level security;revoke all on public.payments from anon,authenticated;create policy payments_tenant on public.payments for select to authenticated using(tenant_id=public.current_tenant_id());insert into public.permissions(code,name,description) values('payments.read','Read payments','View payment history'),('payments.create','Create payments','Record payments'),('payments.update','Update payments','Update payments'),('payments.delete','Delete payments','Void payments') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF') and p.code like 'payments.%' on conflict do nothing;
